1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"syscall"
12	)
13	
14	// BuiltinVersionID identifies the built-in rule version, which reproduces
15	// the original fixed rules. It is always available, its parameters are
16	// queryable, and it cannot be overridden.
17	const BuiltinVersionID = "builtin"
18	
19	// ErrUnknownVersion reports a reference to a rule version that was never
20	// registered in the archive.
21	var ErrUnknownVersion = errors.New("unknown version")
22	
23	// ErrVersionConflict reports a re-registration of an existing version ID
24	// with different parameters.
25	var ErrVersionConflict = errors.New("version already registered with different parameters")
26	
27	// ErrCorruptVersion reports a version whose stored archive document no
28	// longer satisfies the registration rules: a rule object or a required
29	// field is missing or null, a value has the wrong type, or a severity or
30	// multiplier is out of range. The decoded struct cannot tell a missing
31	// field from an explicit zero value, so such an archive would otherwise
32	// run under silently zeroed parameters (a zero displacement multiplier
33	// even crashes detection). Showing, comparing, evaluating or replaying a
34	// corrupt version is refused; the corrupt content is never replaced by the
35	// enabled version, the built-in rules or defaults.
36	var ErrCorruptVersion = errors.New("archived rule version is corrupted")
37	
38	// SandwichRule configures the sandwich rule: whether it runs and the
39	// severity of its conclusions.
40	type SandwichRule struct {
41		Enabled  bool `json:"enabled"`
42		Severity int  `json:"severity"`
43	}
44	
45	// DisplacementRule configures the displacement rule. A victim is flagged
46	// only when the previous swap's GasPrice strictly exceeds Multiplier times
47	// the victim's.
48	type DisplacementRule struct {
49		Enabled    bool `json:"enabled"`
50		Severity   int  `json:"severity"`
51		Multiplier int  `json:"multiplier"`
52	}
53	
54	// RuleSet is the complete declaration of both detection rules. Every
55	// version must declare both rules in full.
56	type RuleSet struct {
57		Sandwich     SandwichRule     `json:"sandwich"`
58		Displacement DisplacementRule `json:"displacement"`
59	}
60	
61	// RuleVersion is a named, immutable set of rule parameters.
62	type RuleVersion struct {
63		ID    string  `json:"id"`
64		Rules RuleSet `json:"rules"`
65	}
66	
67	// BuiltinVersion returns the version representing the original fixed
68	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
69	func BuiltinVersion() RuleVersion {
70		return RuleVersion{
71			ID: BuiltinVersionID,
72			Rules: RuleSet{
73				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
74				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
75			},
76		}
77	}
78	
79	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
80	// distinguish a missing field from an explicit zero value, and the decoder
81	// rejects unknown fields (including unknown rule names).
82	type toggleSpec struct {
83		Enabled  *bool `json:"enabled"`
84		Severity *int  `json:"severity"`
85	}
86	
87	type displacementSpec struct {
88		Enabled    *bool `json:"enabled"`
89		Severity   *int  `json:"severity"`
90		Multiplier *int  `json:"multiplier"`
91	}
92	
93	type versionSpec struct {
94		ID    *string `json:"id"`
95		Rules *struct {
96			Sandwich     *toggleSpec       `json:"sandwich"`
97			Displacement *displacementSpec `json:"displacement"`
98		} `json:"rules"`
99	}
100	
101	func parseEnabled(name string, v *bool) (bool, error) {
102		if v == nil {
103			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
104		}
105		return *v, nil
106	}
107	
108	func parseSeverity(name string, v *int) (int, error) {
109		if v == nil {
110			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
111		}
112		if *v < 1 || *v > 5 {
113			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
114		}
115		return *v, nil
116	}
117	
118	// ErrDuplicateField reports a JSON object in a registration spec that
119	// names the same field twice. Field names are compared the way JSON
120	// decoding matches struct fields, so two spellings the decoder folds
121	// together — differing only in case, like "severity" and "Severity", or
122	// using a compatibility character, like "ſeverity" (U+017F for s) — are
123	// also duplicates.
124	var ErrDuplicateField = errors.New("duplicate field in version spec")
125	
126	// ErrTrailingData reports non-whitespace content after the single JSON
127	// object that makes up a registration spec: a second object, another
128	// JSON value, an unmatched bracket or any other character.
129	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
130	
131	// versionScanPolicy validates the shape of a rule version document with
132	// the shared scanner while keeping version-spec wording and sentinel
133	// errors.
134	var versionScanPolicy = specPolicy{
135		topObject:          "version spec",
136		known:              versionFields,
137		nested:             versionNestedTables,
138		rejectExactUnknown: true,
139		firstTokenError: func(err error) error {
140			if errors.Is(err, io.EOF) {
141				return errors.New("version spec must be a JSON object, got empty input")
142			}
143			return fmt.Errorf("invalid version spec: %w", err)
144		},
145		nonObject: func(tok json.Token) error {
146			if tok == nil {
147				return errors.New("version spec must be a JSON object, got null")
148			}
149			if d, ok := tok.(json.Delim); ok && d == '[' {
150				return errors.New("version spec must be a single JSON object, got array")
151			}
152			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
153		},
154		wrap: func(err error) error {
155			return fmt.Errorf("invalid version spec: %w", err)
156		},
157		duplicate: func(obj, field, first, _ string) error {
158			return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
159		},
160		trailing: versionTrailingData,
161	}
162	
163	// validateSpecStructure proves raw contains exactly one JSON object with
164	// no repeated fields anywhere in it, and nothing but whitespace around
165	// it. Keys are matched against the known fields of the version, rules,
166	// sandwich and displacement objects with the decoder's own field-name
167	// folding: "SEVERITY", "severity" and "ſeverity" (U+017F for s) all point
168	// at the same field and cannot share one object. Escaped key spellings
169	// are decoded before comparison, so "severity" cannot evade it.
170	func validateSpecStructure(raw []byte) error {
171		return scanJSONObject(raw, versionScanPolicy)
172	}
173	
174	// versionTrailingData names the first non-whitespace byte after the
175	// closed object, so an unmatched '}' or ']' is reported directly rather
176	// than as a syntax error; only whitespace may follow the object.
177	func versionTrailingData(raw []byte, offset int) error {
178		rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
179		if len(rest) > 0 {
180			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
181		}
182		return nil
183	}
184	
185	var (
186		versionFields       = fieldTable("id", "rules")
187		rulesFields         = fieldTable("sandwich", "displacement")
188		sandwichFields      = fieldTable("enabled", "severity")
189		displacementFields  = fieldTable("enabled", "severity", "multiplier")
190		versionNestedTables = map[string]nestedObjectSpec{
191			"rules":        {rulesFields, "rules object"},
192			"sandwich":     {sandwichFields, "rules.sandwich"},
193			"displacement": {displacementFields, "rules.displacement"},
194		}
195	)
196	
197	// ParseRuleVersion validates a registration document. It must contain
198	// exactly one complete JSON object (leading and trailing whitespace
199	// allowed): a second object or value, an unmatched bracket or any other
200	// trailing character fails, and empty input, arrays and null are not
201	// specs. Duplicate fields are rejected at the top level, in rules and in
202	// each rule's parameters, including any spellings the decoder folds onto
203	// the same known field (case variants, U+017F for s, and the like). Missing fields, wrong types, out-of-range values and unknown
204	// rules or fields all fail with a reason.
205	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
206		if err := validateSpecStructure(raw); err != nil {
207			return RuleVersion{}, err
208		}
209		var spec versionSpec
210		dec := json.NewDecoder(bytes.NewReader(raw))
211		dec.DisallowUnknownFields()
212		if err := dec.Decode(&spec); err != nil {
213			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
214		}
215		if spec.ID == nil || *spec.ID == "" {
216			return RuleVersion{}, errors.New("id must be a non-empty string")
217		}
218		if spec.Rules == nil {
219			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
220		}
221		if spec.Rules.Sandwich == nil {
222			return RuleVersion{}, errors.New("rules.sandwich is required")
223		}
224		if spec.Rules.Displacement == nil {
225			return RuleVersion{}, errors.New("rules.displacement is required")
226		}
227		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
228		if err != nil {
229			return RuleVersion{}, err
230		}
231		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
232		if err != nil {
233			return RuleVersion{}, err
234		}
235		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
236		if err != nil {
237			return RuleVersion{}, err
238		}
239		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
240		if err != nil {
241			return RuleVersion{}, err
242		}
243		mult := spec.Rules.Displacement.Multiplier
244		if mult == nil {
245			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
246		}
247		if *mult < 2 || *mult > 100 {
248			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
249		}
250		return RuleVersion{
251			ID: *spec.ID,
252			Rules: RuleSet{
253				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
254				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
255			},
256		}, nil
257	}
258	
259	// intactVersion resolves id for a comparison and proves the version's
260	// stored archive document still satisfies every registration rule,
261	// re-validating the raw document with the same parser registrations pass.
262	// The decoded struct cannot do this: a missing enabled, severity or
263	// multiplier field unmarshals as the zero value and is indistinguishable
264	// from an explicitly declared one, and a wrong-typed field fails the
265	// whole-archive decode before any judgment can run. An explicitly
266	// declared false or any in-range value is valid; a missing or null field,
267	// a wrong type or an out-of-range number makes the version corrupt, and
268	// the failure names the version and the offending rule or field. The
269	// built-in version is constructed in code and always intact.
270	func intactVersion(versions []json.RawMessage, id string) (RuleVersion, error) {
271		if id == BuiltinVersionID {
272			return BuiltinVersion(), nil
273		}
274		for _, entry := range versions {
275			if !entryDeclaresID(entry, id) {
276				continue
277			}
278			v, err := ParseRuleVersion(entry)
279			if err != nil {
280				return RuleVersion{}, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, id, err)
281			}
282			return v, nil
283		}
284		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
285	}
286	
287	// entryDeclaresID reports whether the raw version entry carries the given
288	// id, recognising it the way the decoder folds field names — so "id", "ID"
289	// and "ıd"-style compatibility spellings all count — and inspecting every
290	// occurrence rather than decoding the object. A decayed document that
291	// repeats the id key ("id":"x","id":<target>, which a plain unmarshal folds
292	// onto the last value) is therefore still attributed to the registered
293	// version and judged as corruption by ParseRuleVersion, never dismissed as
294	// unknown. Entries that are not JSON objects, or whose id has no string
295	// occurrence equal to target, do not match.
296	func entryDeclaresID(entry json.RawMessage, id string) bool {
297		dec := json.NewDecoder(bytes.NewReader(entry))
298		first, err := dec.Token()
299		if err != nil {
300			return false
301		}
302		if d, ok := first.(json.Delim); !ok || d != '{' {
303			return false
304		}
305		// foldName folds to the smallest rune in each case-folding orbit, so the
306		// folded spelling of "id" is "ID"; fold the key the same way rather than
307		// comparing against the lowercase literal.
308		idField := foldName("id")
309		for dec.More() {
310			keyTok, err := dec.Token()
311			if err != nil {
312				return false
313			}
314			key, _ := keyTok.(string)
315			valTok, err := dec.Token()
316			if err != nil {
317				return false
318			}
319			if _, isDelim := valTok.(json.Delim); isDelim {
320				// Consume the container the id (or another key) points at; an
321				// object/array id is a wrong type, not a matching identity.
322				depth := 1
323				for depth > 0 {
324					tok, err := dec.Token()
325					if err != nil {
326						return false
327					}
328					if dd, ok := tok.(json.Delim); ok {
329						if dd == '{' || dd == '[' {
330							depth++
331						} else {
332							depth--
333						}
334					}
335				}
336				continue
337			}
338			if foldName(key) == idField {
339				if s, ok := valTok.(string); ok && s == id {
340					return true
341				}
342			}
343		}
344		return false
345	}
346	
347	// RegisterVersion validates raw as a rule version spec and stores it in the
348	// archive at dir. Re-registering the same ID with identical parameters
349	// succeeds without adding a version (created is false); the same ID with
350	// different parameters is rejected. The built-in version ID is reserved.
351	// Any failure leaves the archive untouched.
352	//
353	// Registration only ever adds the version this run submitted; it never
354	// repairs, completes, reorders or drops a stored declaration. The archive
355	// is therefore decoded with every registered version kept as its raw stored
356	// document, the same shape a replay or an enable uses: a corrupt sibling —
357	// a missing or null field, a wrong type, an out-of-range number, an unknown
358	// or duplicate field — is that version's damage, not whole-archive
359	// corruption, and neither blocks a legal new registration nor gets silently
360	// completed (a missing enabled would otherwise come back as an explicit
361	// false) or stripped of its unknown fields by one. When the submitted ID is
362	// already taken, the stored declaration must still satisfy the registration
363	// rules in full before any judgment about it: a corrupt one fails with
364	// ErrCorruptVersion naming the version and the offending rule or field —
365	// never created:false against the decayed parameters, never overwritten by
366	// the new ones, never misreported as a parameter conflict.
367	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
368		v, err = ParseRuleVersion(raw)
369		if err != nil {
370			return RuleVersion{}, false, err
371		}
372		if v.ID == BuiltinVersionID {
373			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
374		}
375		if err := os.MkdirAll(dir, 0o755); err != nil {
376			return RuleVersion{}, false, err
377		}
378		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
379		if err != nil {
380			return RuleVersion{}, false, err
381		}
382		defer lock.Close()
383	
384		data := replayArchiveDoc{Records: []json.RawMessage{}}
385		archiveRaw, err := readArchiveBytes(dir)
386		if err != nil {
387			return RuleVersion{}, false, err
388		}
389		if archiveRaw != nil {
390			if err := json.Unmarshal(archiveRaw, &data); err != nil {
391				return RuleVersion{}, false, fmt.Errorf("archive is corrupted: %w", err)
392			}
393		}
394		for _, entry := range data.Versions {
395			if !entryDeclaresID(entry, v.ID) {
396				continue
397			}
398			existing, perr := ParseRuleVersion(entry)
399			if perr != nil {
400				return RuleVersion{}, false, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, v.ID, perr)
401			}
402			if existing.Rules == v.Rules {
403				return existing, false, nil
404			}
405			return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
406		}
407		// The new version is appended as the exact document this run submitted
408		// and validated; every other section — the stored versions in order, the
409		// enabled marker, records, suppressions, alert records and reviews — is
410		// written back unchanged.
411		data.Versions = append(data.Versions, json.RawMessage(raw))
412		if err := writeArchiveAtomic(dir, data); err != nil {
413			return RuleVersion{}, false, err
414		}
415		return v, true, nil
416	}
417	
418	// EnableVersion makes id the archive's active version for later replays
419	// that name no explicit version. Before the marker changes, the selected
420	// version's stored archive document must still satisfy every registration
421	// rule in full — re-validated from its raw bytes with the same parser
422	// registrations pass — even when it is already the enabled version: the
423	// decoded struct cannot tell a decayed or wrong-typed field from an
424	// explicit value, so enabling a corrupt registered version fails with
425	// ErrCorruptVersion rather than succeeding under zeroed parameters and
426	// delaying the failure to the next replay. A version that was never
427	// registered stays an ErrUnknownVersion failure; the built-in version is
428	// constructed in code, needs no registration and is always intact. On
429	// success only the enabled marker changes: every other stored version is
430	// written back byte for byte (fields, values and order preserved, corrupt
431	// siblings included), and reports, suppressions, alert records and reviews
432	// are untouched. Any failure — corruption, an unreadable or busy archive,
433	// a failed write — leaves the archive unchanged.
434	func EnableVersion(dir, id string) (RuleVersion, error) {
435		if id == "" {
436			return RuleVersion{}, errors.New("version id must not be empty")
437		}
438		if err := os.MkdirAll(dir, 0o755); err != nil {
439			return RuleVersion{}, err
440		}
441		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
442		if err != nil {
443			return RuleVersion{}, err
444		}
445		defer lock.Close()
446	
447		// Decode with each registered version kept as its raw stored document,
448		// the same shape a replay uses: a wrong-typed field in one version is
449		// that version's corruption rather than whole-archive corruption, a
450		// corrupt sibling cannot block an intact candidate or builtin, and the
451		// versions not selected are written back verbatim — enabling a version
452		// never completes a missing field, fixes a value, reorders or drops an
453		// entry.
454		raw, err := readArchiveBytes(dir)
455		if err != nil {
456			return RuleVersion{}, err
457		}
458		data := replayArchiveDoc{Records: []json.RawMessage{}}
459		if raw != nil {
460			if err := json.Unmarshal(raw, &data); err != nil {
461				return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
462			}
463		}
464		// Validate the stored declaration before changing anything. An explicit
465		// enabled:false is a legal off state, but a disabled rule still has to
466		// carry complete, in-range parameters; a missing or null rule object or
467		// field, a wrong type, an out-of-range number, an unknown or duplicate
468		// field all fail here. intactVersion returns the built-in version for
469		// the built-in id and an unknown-version error for an id it cannot find.
470		v, err := intactVersion(data.Versions, id)
471		if err != nil {
472			return RuleVersion{}, err
473		}
474		if data.EnabledVersion == id {
475			return v, nil
476		}
477		data.EnabledVersion = id
478		if err := writeArchiveAtomic(dir, data); err != nil {
479			return RuleVersion{}, err
480		}
481		return v, nil
482	}
483	
484	// identifiableVersionID recovers the best human-recognizable identifier a
485	// stored version document still carries for an error message: the last
486	// string occurrence of its id key, recognising it the way the decoder folds
487	// field names — "id", "ID" and "ıd"-style compatibility spellings all
488	// count. The last occurrence is what a plain unmarshal surfaces, so a
489	// decayed document that repeats the id key ("id":"x","id":"y") is reported
490	// under the id a reader sees in the decoded file rather than claimed to be
491	// the earlier one. A document that is not an object, or carries no string
492	// id at all, has no identifiable version; its corruption is still reported
493	// (ParseRuleVersion judges the document), just without a made-up name.
494	func identifiableVersionID(entry json.RawMessage) string {
495		const unidentifiable = "unidentifiable version"
496		dec := json.NewDecoder(bytes.NewReader(entry))
497		first, err := dec.Token()
498		if err != nil {
499			return unidentifiable
500		}
501		if d, ok := first.(json.Delim); !ok || d != '{' {
502			return unidentifiable
503		}
504		idField := foldName("id")
505		last := ""
506		found := false
507		for dec.More() {
508			keyTok, err := dec.Token()
509			if err != nil {
510				return unidentifiable
511			}
512			key, _ := keyTok.(string)
513			valTok, err := dec.Token()
514			if err != nil {
515				return unidentifiable
516			}
517			if _, isDelim := valTok.(json.Delim); isDelim {
518				// Consume the container the id (or another key) points at; an
519				// object/array id is a wrong type, not an identifier.
520				depth := 1
521				for depth > 0 {
522					tok, err := dec.Token()
523					if err != nil {
524						return unidentifiable
525					}
526					if dd, ok := tok.(json.Delim); ok {
527						if dd == '{' || dd == '[' {
528							depth++
529						} else {
530							depth--
531						}
532					}
533				}
534				continue
535			}
536			if foldName(key) == idField {
537				if s, ok := valTok.(string); ok && s != "" {
538					last, found = s, true
539				}
540			}
541		}
542		if !found {
543			return unidentifiable
544		}
545		return last
546	}
547	
548	// ListVersions returns the built-in version plus every version registered
549	// in the archive, along with the currently enabled version ID.
550	//
551	// Every registered version's stored archive document must still satisfy
552	// the registration rules in full — sandwich and displacement each
553	// declaring enabled and severity, displacement also multiplier, severity
554	// an integer 1-5 and multiplier an integer 2-100 — re-validated from its
555	// raw bytes with the same parser registration, enable, comparison, replay
556	// and show use, before a single version is returned. The decoded struct
557	// cannot tell a missing or null enabled, severity or multiplier from an
558	// explicitly declared one (a missing enabled renders as false, a missing
559	// multiplier as 0), and a wrong-typed field fails the whole-archive decode
560	// before any judgment can run; listing off the structs directly would
561	// therefore display a decayed declaration with silently zeroed parameters,
562	// erasing the difference between a genuinely switched-off rule and a lost
563	// field. Unknown rules or fields and repeated fields in one object
564	// (including the case-folded and escaped spellings registration rejects)
565	// are damage of the same kind. One corrupt registered version therefore
566	// fails the whole listing with ErrCorruptVersion — whether or not it is
567	// the enabled one, wherever it sits in the archive — naming the version's
568	// identifiable stored id and the offending rule or field; no full or
569	// partial list is returned, and the corrupt entry is never skipped past,
570	// repaired, completed or replaced by the enabled version, the built-in
571	// rules or defaults.
572	//
573	// An explicitly declared enabled:false is a legal off state: such a
574	// version, including one with both rules disabled, is listed normally
575	// with its complete parameters. The built-in version leads the list,
576	// registered versions follow in stored order with their id strings
577	// verbatim, and the enabled marker is reported as builtin when the
578	// archive names none. A missing archive directory or a legacy archive
579	// without versions and an enabled marker yields just the built-in
580	// version with its original parameters; a wholly unparseable archive
581	// stays an archive-corruption error rather than "no versions". The
582	// query is read-only: it never repairs, completes, deletes or rewrites
583	// any stored declaration or anything else in the archive.
584	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
585		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
586			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
587		}
588		lock, err := lockArchive(dir, syscall.LOCK_SH)
589		if err != nil {
590			return nil, "", err
591		}
592		defer lock.Close()
593	
594		// Decode with each registered version kept as its raw stored document,
595		// the same shape every other version query uses: a wrong-typed field in
596		// one version is that version's corruption rather than whole-archive
597		// corruption, and every entry is judged on its own before the list is
598		// returned — listing never zero-fills, completes or drops an entry.
599		raw, err := readArchiveBytes(dir)
600		if err != nil {
601			return nil, "", err
602		}
603		data := replayArchiveDoc{Records: []json.RawMessage{}}
604		if raw != nil {
605			if err := json.Unmarshal(raw, &data); err != nil {
606				return nil, "", fmt.Errorf("archive is corrupted: %w", err)
607			}
608		}
609	
610		versions = make([]RuleVersion, 0, len(data.Versions)+1)
611		versions = append(versions, BuiltinVersion())
612		for _, entry := range data.Versions {
613			v, perr := ParseRuleVersion(entry)
614			if perr != nil {
615				return nil, "", fmt.Errorf("%w: %s: %w", ErrCorruptVersion, identifiableVersionID(entry), perr)
616			}
617			versions = append(versions, v)
618		}
619		enabled = data.EnabledVersion
620		if enabled == "" {
621			enabled = BuiltinVersionID
622		}
623		return versions, enabled, nil
624	}
625	
626	// GetVersion returns one version's full parameters by ID. The requested
627	// version's stored archive document must still satisfy every registration
628	// rule in full — re-validated from its raw bytes with the same parser
629	// registrations pass — before its parameters are returned: the decoded
630	// struct cannot tell a missing enabled, severity or multiplier from an
631	// explicitly declared one, so a corrupt declaration would otherwise be
632	// shown with silently zeroed or defaulted parameters. An explicit
633	// enabled:false is a legal off state, but a disabled rule still has to
634	// carry complete, in-range parameters; a missing or null rule object or
635	// field, a wrong type, an out-of-range number, an unknown or duplicate
636	// field all fail with ErrCorruptVersion naming the version and the
637	// offending rule or field — never completed from defaults, the enabled
638	// version or the built-in rules. Only the requested version is judged: a
639	// corrupt sibling — even the currently enabled one — does not block
640	// showing an intact version, and an id that no stored declaration carries
641	// stays an ErrUnknownVersion failure (the id string is matched exactly,
642	// never case-folded or trimmed). The built-in version is constructed in
643	// code and always queryable, whether or not the archive directory exists.
644	// A wholly unparseable archive still fails as archive corruption. The
645	// query is read-only: version declarations, the enabled marker and the
646	// archived reports are never modified.
647	func GetVersion(dir, id string) (RuleVersion, error) {
648		if id == BuiltinVersionID {
649			return BuiltinVersion(), nil
650		}
651		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
652			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
653		}
654		lock, err := lockArchive(dir, syscall.LOCK_SH)
655		if err != nil {
656			return RuleVersion{}, err
657		}
658		defer lock.Close()
659	
660		// Decode with each registered version kept as its raw stored document,
661		// the same shape a replay or an enable uses: a wrong-typed field in one
662		// version is that version's corruption rather than whole-archive
663		// corruption, and a corrupt sibling cannot block an intact candidate.
664		raw, err := readArchiveBytes(dir)
665		if err != nil {
666			return RuleVersion{}, err
667		}
668		data := replayArchiveDoc{Records: []json.RawMessage{}}
669		if raw != nil {
670			if err := json.Unmarshal(raw, &data); err != nil {
671				return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
672			}
673		}
674		return intactVersion(data.Versions, id)
675	}
676	
677	// FindingChange pairs the archived and compared conclusions for one
678	// transaction whose kind or severity differs between the two versions.
679	type FindingChange struct {
680		TxHash   string        `json:"txHash"`
681		Original ReportFinding `json:"original"`
682		Compared ReportFinding `json:"compared"`
683	}
684	
685	// CompareResult is the outcome of re-judging one archived block under a
686	// different rule version. It carries both versions' parameters, both full
687	// conclusion sets, the raw swap evidence, and the per-transaction diff.
688	type CompareResult struct {
689		ChainID          string          `json:"chainId"`
690		BlockHash        string          `json:"blockHash"`
691		BlockNumber      int64           `json:"blockNumber"`
692		OriginalVersion  RuleVersion     `json:"originalVersion"`
693		ComparedVersion  RuleVersion     `json:"comparedVersion"`
694		OriginalFindings []ReportFinding `json:"originalFindings"`
695		ComparedFindings []ReportFinding `json:"comparedFindings"`
696		Swaps            []Swap          `json:"swaps"`
697		Added            []ReportFinding `json:"added"`
698		Removed          []ReportFinding `json:"removed"`
699		Changed          []FindingChange `json:"changed"`
700	}
701	
702	// compareArchiveDoc mirrors the archive file the way a comparison reads
703	// it: the embedded version declaration of every record is kept as its raw
704	// stored document (queryRecord), the same shape a report query, a replay
705	// and alert generation use, and each registered version is kept raw too.
706	// A wrong-typed or decayed field in one saved declaration then cannot
707	// break the read or masquerade as whole-archive corruption, and — crucially
708	// — cannot decode into silently zeroed parameters or be explained as the
709	// built-in rules from a written null: the target record's declaration is
710	// judged on its own from those bytes before any comparison is returned.
711	type compareArchiveDoc struct {
712		Records  []queryRecord     `json:"records"`
713		Versions []json.RawMessage `json:"versions"`
714	}
715	
716	// Compare re-runs detection for one archived block under the given
717	// registered version and diffs the conclusions against the archived
718	// report. It only reads the archive: the original input file is not
719	// needed, and neither the archived report nor the enabled version is
720	// modified.
721	//
722	// The historical side is the target block's own saved report and is held
723	// to exactly the integrity proof a report query enforces before any
724	// result is returned: its declaration is re-validated from the raw stored
725	// bytes — a non-empty id, sandwich and displacement each declaring a
726	// boolean enabled and an integer severity 1-5, and a displacement
727	// multiplier 2-100; a missing or null field or rule object, a wrong type,
728	// an out-of-range number, an unknown field or rule, or a field declared
729	// twice in one object (an exact repeat, an escaped spelling or a
730	// case-only spelling naming the same field, even with identical values;
731	// the two rules declaring their own parameters side by side is not a
732	// repeat) makes the saved declaration corrupt. An explicit enabled:false
733	// is a legal off state, but the disabled rule still has to carry
734	// complete, in-range parameters. Only an old-format record with no
735	// version key at all keeps the built-in interpretation: a written null,
736	// an empty object or an incomplete declaration is corruption, and an id
737	// of "builtin" names the same saved declaration and cannot bypass the
738	// check. A legal candidate version never rescues a damaged historical
739	// declaration: the whole comparison fails with ErrCorruptVersion naming
740	// the target chain and block, the readable saved version id and the
741	// offending rule or field — even when the block has no swaps or its
742	// archived findings are empty, so no empty comparison can skip the
743	// proof. The historical parameters come from that report alone, never
744	// from the currently enabled or a same-id registered version, and the
745	// saved id need not still be registered.
746	//
747	// The named candidate version's stored document must likewise still
748	// satisfy the registration rules in full; a corrupt one fails with
749	// ErrCorruptVersion rather than comparing under zeroed or substituted
750	// parameters. An unknown block stays ErrUnknownBlock and an unknown or
751	// corrupt candidate version keeps its existing error behavior.
752	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
753		if _, err := os.Stat(dir); err != nil {
754			if errors.Is(err, os.ErrNotExist) {
755				return CompareResult{}, ErrUnknownBlock
756			}
757			return CompareResult{}, err
758		}
759		lock, err := lockArchive(dir, syscall.LOCK_SH)
760		if err != nil {
761			return CompareResult{}, err
762		}
763		defer lock.Close()
764	
765		raw, err := readArchiveBytes(dir)
766		if err != nil {
767			return CompareResult{}, err
768		}
769		var doc compareArchiveDoc
770		if len(raw) > 0 {
771			if err := json.Unmarshal(raw, &doc); err != nil {
772				return CompareResult{}, fmt.Errorf("archive is corrupted: %w", err)
773			}
774		}
775		var rec *queryRecord
776		for i := range doc.Records {
777			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
778				rec = &doc.Records[i]
779				break
780			}
781		}
782		if rec == nil {
783			return CompareResult{}, ErrUnknownBlock
784		}
785		// The historical side is this block's own saved report and has to pass
786		// exactly the integrity proof a report query demands before any result
787		// is returned — re-validated from the declaration's raw stored bytes,
788		// not the decoded struct. A written null would otherwise leave the
789		// version pointer nil and be explained as the built-in rules, and a
790		// missing enabled/severity/multiplier would decode as an explicit zero
791		// value and compare under silently zeroed parameters; an empty object,
792		// a wrong type, an out-of-range number, an unknown rule or field and a
793		// repeated field are damage of the same kind. A legal candidate can
794		// never rescue this declaration, and the check runs unconditionally —
795		// even for a block with no swaps or an empty findings array — so no
796		// empty comparison can skip it. Only a wholly absent version key (a
797		// zero-length RawMessage) is the legacy shape explained by builtin.
798		originalVersion, err := archivedReportVersion(rec.Version)
799		if err != nil {
800			return CompareResult{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
801		}
802		// The requested candidate version must also be intact in the archive:
803		// re-validate its stored document before judging anything, so a corrupt
804		// version fails the same way even when the block has no swaps and
805		// detection would produce no conclusions at all.
806		compared, err := intactVersion(doc.Versions, versionID)
807		if err != nil {
808			return CompareResult{}, err
809		}
810		original := rec.Findings
811		if original == nil {
812			original = []ReportFinding{}
813		}
814		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
815		swaps := rec.Swaps
816		if swaps == nil {
817			swaps = []Swap{}
818		}
819	
820		origByTx := make(map[string]ReportFinding, len(original))
821		for _, f := range original {
822			origByTx[f.TxHash] = f
823		}
824		compByTx := make(map[string]ReportFinding, len(rejudged))
825		for _, f := range rejudged {
826			compByTx[f.TxHash] = f
827		}
828		added := []ReportFinding{}
829		removed := []ReportFinding{}
830		changed := []FindingChange{}
831		for _, f := range rejudged {
832			if o, ok := origByTx[f.TxHash]; ok {
833				// A transaction present on both sides with a different kind or
834				// severity is a change, never an add plus a remove.
835				if o.Kind != f.Kind || o.Severity != f.Severity {
836					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
837				}
838			} else {
839				added = append(added, f)
840			}
841		}
842		for _, f := range original {
843			if _, ok := compByTx[f.TxHash]; !ok {
844				removed = append(removed, f)
845			}
846		}
847		byTx := func(fs []ReportFinding) {
848			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
849		}
850		byTx(added)
851		byTx(removed)
852		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
853	
854		return CompareResult{
855			ChainID:          rec.ChainID,
856			BlockHash:        rec.BlockHash,
857			BlockNumber:      rec.BlockNumber,
858			OriginalVersion:  originalVersion,
859			ComparedVersion:  compared,
860			OriginalFindings: original,
861			ComparedFindings: rejudged,
862			Swaps:            swaps,
863			Added:            added,
864			Removed:          removed,
865			Changed:          changed,
866		}, nil
867	}
868

file.content:
package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"sort"
	"syscall"
)

// BuiltinVersionID identifies the built-in rule version, which reproduces
// the original fixed rules. It is always available, its parameters are
// queryable, and it cannot be overridden.
const BuiltinVersionID = "builtin"

// ErrUnknownVersion reports a reference to a rule version that was never
// registered in the archive.
var ErrUnknownVersion = errors.New("unknown version")

// ErrVersionConflict reports a re-registration of an existing version ID
// with different parameters.
var ErrVersionConflict = errors.New("version already registered with different parameters")

// ErrCorruptVersion reports a version whose stored archive document no
// longer satisfies the registration rules: a rule object or a required
// field is missing or null, a value has the wrong type, or a severity or
// multiplier is out of range. The decoded struct cannot tell a missing
// field from an explicit zero value, so such an archive would otherwise
// run under silently zeroed parameters (a zero displacement multiplier
// even crashes detection). Showing, comparing, evaluating or replaying a
// corrupt version is refused; the corrupt content is never replaced by the
// enabled version, the built-in rules or defaults.
var ErrCorruptVersion = errors.New("archived rule version is corrupted")

// SandwichRule configures the sandwich rule: whether it runs and the
// severity of its conclusions.
type SandwichRule struct {
	Enabled  bool `json:"enabled"`
	Severity int  `json:"severity"`
}

// DisplacementRule configures the displacement rule. A victim is flagged
// only when the previous swap's GasPrice strictly exceeds Multiplier times
// the victim's.
type DisplacementRule struct {
	Enabled    bool `json:"enabled"`
	Severity   int  `json:"severity"`
	Multiplier int  `json:"multiplier"`
}

// RuleSet is the complete declaration of both detection rules. Every
// version must declare both rules in full.
type RuleSet struct {
	Sandwich     SandwichRule     `json:"sandwich"`
	Displacement DisplacementRule `json:"displacement"`
}

// RuleVersion is a named, immutable set of rule parameters.
type RuleVersion struct {
	ID    string  `json:"id"`
	Rules RuleSet `json:"rules"`
}

// BuiltinVersion returns the version representing the original fixed
// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
func BuiltinVersion() RuleVersion {
	return RuleVersion{
		ID: BuiltinVersionID,
		Rules: RuleSet{
			Sandwich:     SandwichRule{Enabled: true, Severity: 3},
			Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
		},
	}
}

// toggleSpec and displacementSpec mirror the registration JSON. Pointers
// distinguish a missing field from an explicit zero value, and the decoder
// rejects unknown fields (including unknown rule names).
type toggleSpec struct {
	Enabled  *bool `json:"enabled"`
	Severity *int  `json:"severity"`
}

type displacementSpec struct {
	Enabled    *bool `json:"enabled"`
	Severity   *int  `json:"severity"`
	Multiplier *int  `json:"multiplier"`
}

type versionSpec struct {
	ID    *string `json:"id"`
	Rules *struct {
		Sandwich     *toggleSpec       `json:"sandwich"`
		Displacement *displacementSpec `json:"displacement"`
	} `json:"rules"`
}

func parseEnabled(name string, v *bool) (bool, error) {
	if v == nil {
		return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
	}
	return *v, nil
}

func parseSeverity(name string, v *int) (int, error) {
	if v == nil {
		return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
	}
	if *v < 1 || *v > 5 {
		return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
	}
	return *v, nil
}

// ErrDuplicateField reports a JSON object in a registration spec that
// names the same field twice. Field names are compared the way JSON
// decoding matches struct fields, so two spellings the decoder folds
// together — differing only in case, like "severity" and "Severity", or
// using a compatibility character, like "ſeverity" (U+017F for s) — are
// also duplicates.
var ErrDuplicateField = errors.New("duplicate field in version spec")

// ErrTrailingData reports non-whitespace content after the single JSON
// object that makes up a registration spec: a second object, another
// JSON value, an unmatched bracket or any other character.
var ErrTrailingData = errors.New("unexpected trailing data after version spec")

// versionScanPolicy validates the shape of a rule version document with
// the shared scanner while keeping version-spec wording and sentinel
// errors.
var versionScanPolicy = specPolicy{
	topObject:          "version spec",
	known:              versionFields,
	nested:             versionNestedTables,
	rejectExactUnknown: true,
	firstTokenError: func(err error) error {
		if errors.Is(err, io.EOF) {
			return errors.New("version spec must be a JSON object, got empty input")
		}
		return fmt.Errorf("invalid version spec: %w", err)
	},
	nonObject: func(tok json.Token) error {
		if tok == nil {
			return errors.New("version spec must be a JSON object, got null")
		}
		if d, ok := tok.(json.Delim); ok && d == '[' {
			return errors.New("version spec must be a single JSON object, got array")
		}
		return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
	},
	wrap: func(err error) error {
		return fmt.Errorf("invalid version spec: %w", err)
	},
	duplicate: func(obj, field, first, _ string) error {
		return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
	},
	trailing: versionTrailingData,
}

// validateSpecStructure proves raw contains exactly one JSON object with
// no repeated fields anywhere in it, and nothing but whitespace around
// it. Keys are matched against the known fields of the version, rules,
// sandwich and displacement objects with the decoder's own field-name
// folding: "SEVERITY", "severity" and "ſeverity" (U+017F for s) all point
// at the same field and cannot share one object. Escaped key spellings
// are decoded before comparison, so "severity" cannot evade it.
func validateSpecStructure(raw []byte) error {
	return scanJSONObject(raw, versionScanPolicy)
}

// versionTrailingData names the first non-whitespace byte after the
// closed object, so an unmatched '}' or ']' is reported directly rather
// than as a syntax error; only whitespace may follow the object.
func versionTrailingData(raw []byte, offset int) error {
	rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
	if len(rest) > 0 {
		return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
	}
	return nil
}

var (
	versionFields       = fieldTable("id", "rules")
	rulesFields         = fieldTable("sandwich", "displacement")
	sandwichFields      = fieldTable("enabled", "severity")
	displacementFields  = fieldTable("enabled", "severity", "multiplier")
	versionNestedTables = map[string]nestedObjectSpec{
		"rules":        {rulesFields, "rules object"},
		"sandwich":     {sandwichFields, "rules.sandwich"},
		"displacement": {displacementFields, "rules.displacement"},
	}
)

// ParseRuleVersion validates a registration document. It must contain
// exactly one complete JSON object (leading and trailing whitespace
// allowed): a second object or value, an unmatched bracket or any other
// trailing character fails, and empty input, arrays and null are not
// specs. Duplicate fields are rejected at the top level, in rules and in
// each rule's parameters, including any spellings the decoder folds onto
// the same known field (case variants, U+017F for s, and the like). Missing fields, wrong types, out-of-range values and unknown
// rules or fields all fail with a reason.
func ParseRuleVersion(raw []byte) (RuleVersion, error) {
	if err := validateSpecStructure(raw); err != nil {
		return RuleVersion{}, err
	}
	var spec versionSpec
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&spec); err != nil {
		return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
	}
	if spec.ID == nil || *spec.ID == "" {
		return RuleVersion{}, errors.New("id must be a non-empty string")
	}
	if spec.Rules == nil {
		return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
	}
	if spec.Rules.Sandwich == nil {
		return RuleVersion{}, errors.New("rules.sandwich is required")
	}
	if spec.Rules.Displacement == nil {
		return RuleVersion{}, errors.New("rules.displacement is required")
	}
	sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
	if err != nil {
		return RuleVersion{}, err
	}
	sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
	if err != nil {
		return RuleVersion{}, err
	}
	dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
	if err != nil {
		return RuleVersion{}, err
	}
	dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
	if err != nil {
		return RuleVersion{}, err
	}
	mult := spec.Rules.Displacement.Multiplier
	if mult == nil {
		return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
	}
	if *mult < 2 || *mult > 100 {
		return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
	}
	return RuleVersion{
		ID: *spec.ID,
		Rules: RuleSet{
			Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
			Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
		},
	}, nil
}

// intactVersion resolves id for a comparison and proves the version's
// stored archive document still satisfies every registration rule,
// re-validating the raw document with the same parser registrations pass.
// The decoded struct cannot do this: a missing enabled, severity or
// multiplier field unmarshals as the zero value and is indistinguishable
// from an explicitly declared one, and a wrong-typed field fails the
// whole-archive decode before any judgment can run. An explicitly
// declared false or any in-range value is valid; a missing or null field,
// a wrong type or an out-of-range number makes the version corrupt, and
// the failure names the version and the offending rule or field. The
// built-in version is constructed in code and always intact.
func intactVersion(versions []json.RawMessage, id string) (RuleVersion, error) {
	if id == BuiltinVersionID {
		return BuiltinVersion(), nil
	}
	for _, entry := range versions {
		if !entryDeclaresID(entry, id) {
			continue
		}
		v, err := ParseRuleVersion(entry)
		if err != nil {
			return RuleVersion{}, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, id, err)
		}
		return v, nil
	}
	return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
}

// entryDeclaresID reports whether the raw version entry carries the given
// id, recognising it the way the decoder folds field names — so "id", "ID"
// and "ıd"-style compatibility spellings all count — and inspecting every
// occurrence rather than decoding the object. A decayed document that
// repeats the id key ("id":"x","id":<target>, which a plain unmarshal folds
// onto the last value) is therefore still attributed to the registered
// version and judged as corruption by ParseRuleVersion, never dismissed as
// unknown. Entries that are not JSON objects, or whose id has no string
// occurrence equal to target, do not match.
func entryDeclaresID(entry json.RawMessage, id string) bool {
	dec := json.NewDecoder(bytes.NewReader(entry))
	first, err := dec.Token()
	if err != nil {
		return false
	}
	if d, ok := first.(json.Delim); !ok || d != '{' {
		return false
	}
	// foldName folds to the smallest rune in each case-folding orbit, so the
	// folded spelling of "id" is "ID"; fold the key the same way rather than
	// comparing against the lowercase literal.
	idField := foldName("id")
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return false
		}
		key, _ := keyTok.(string)
		valTok, err := dec.Token()
		if err != nil {
			return false
		}
		if _, isDelim := valTok.(json.Delim); isDelim {
			// Consume the container the id (or another key) points at; an
			// object/array id is a wrong type, not a matching identity.
			depth := 1
			for depth > 0 {
				tok, err := dec.Token()
				if err != nil {
					return false
				}
				if dd, ok := tok.(json.Delim); ok {
					if dd == '{' || dd == '[' {
						depth++
					} else {
						depth--
					}
				}
			}
			continue
		}
		if foldName(key) == idField {
			if s, ok := valTok.(string); ok && s == id {
				return true
			}
		}
	}
	return false
}

// RegisterVersion validates raw as a rule version spec and stores it in the
// archive at dir. Re-registering the same ID with identical parameters
// succeeds without adding a version (created is false); the same ID with
// different parameters is rejected. The built-in version ID is reserved.
// Any failure leaves the archive untouched.
//
// Registration only ever adds the version this run submitted; it never
// repairs, completes, reorders or drops a stored declaration. The archive
// is therefore decoded with every registered version kept as its raw stored
// document, the same shape a replay or an enable uses: a corrupt sibling —
// a missing or null field, a wrong type, an out-of-range number, an unknown
// or duplicate field — is that version's damage, not whole-archive
// corruption, and neither blocks a legal new registration nor gets silently
// completed (a missing enabled would otherwise come back as an explicit
// false) or stripped of its unknown fields by one. When the submitted ID is
// already taken, the stored declaration must still satisfy the registration
// rules in full before any judgment about it: a corrupt one fails with
// ErrCorruptVersion naming the version and the offending rule or field —
// never created:false against the decayed parameters, never overwritten by
// the new ones, never misreported as a parameter conflict.
func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
	v, err = ParseRuleVersion(raw)
	if err != nil {
		return RuleVersion{}, false, err
	}
	if v.ID == BuiltinVersionID {
		return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return RuleVersion{}, false, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return RuleVersion{}, false, err
	}
	defer lock.Close()

	data := replayArchiveDoc{Records: []json.RawMessage{}}
	archiveRaw, err := readArchiveBytes(dir)
	if err != nil {
		return RuleVersion{}, false, err
	}
	if archiveRaw != nil {
		if err := json.Unmarshal(archiveRaw, &data); err != nil {
			return RuleVersion{}, false, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	for _, entry := range data.Versions {
		if !entryDeclaresID(entry, v.ID) {
			continue
		}
		existing, perr := ParseRuleVersion(entry)
		if perr != nil {
			return RuleVersion{}, false, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, v.ID, perr)
		}
		if existing.Rules == v.Rules {
			return existing, false, nil
		}
		return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
	}
	// The new version is appended as the exact document this run submitted
	// and validated; every other section — the stored versions in order, the
	// enabled marker, records, suppressions, alert records and reviews — is
	// written back unchanged.
	data.Versions = append(data.Versions, json.RawMessage(raw))
	if err := writeArchiveAtomic(dir, data); err != nil {
		return RuleVersion{}, false, err
	}
	return v, true, nil
}

// EnableVersion makes id the archive's active version for later replays
// that name no explicit version. Before the marker changes, the selected
// version's stored archive document must still satisfy every registration
// rule in full — re-validated from its raw bytes with the same parser
// registrations pass — even when it is already the enabled version: the
// decoded struct cannot tell a decayed or wrong-typed field from an
// explicit value, so enabling a corrupt registered version fails with
// ErrCorruptVersion rather than succeeding under zeroed parameters and
// delaying the failure to the next replay. A version that was never
// registered stays an ErrUnknownVersion failure; the built-in version is
// constructed in code, needs no registration and is always intact. On
// success only the enabled marker changes: every other stored version is
// written back byte for byte (fields, values and order preserved, corrupt
// siblings included), and reports, suppressions, alert records and reviews
// are untouched. Any failure — corruption, an unreadable or busy archive,
// a failed write — leaves the archive unchanged.
func EnableVersion(dir, id string) (RuleVersion, error) {
	if id == "" {
		return RuleVersion{}, errors.New("version id must not be empty")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return RuleVersion{}, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
	if err != nil {
		return RuleVersion{}, err
	}
	defer lock.Close()

	// Decode with each registered version kept as its raw stored document,
	// the same shape a replay uses: a wrong-typed field in one version is
	// that version's corruption rather than whole-archive corruption, a
	// corrupt sibling cannot block an intact candidate or builtin, and the
	// versions not selected are written back verbatim — enabling a version
	// never completes a missing field, fixes a value, reorders or drops an
	// entry.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return RuleVersion{}, err
	}
	data := replayArchiveDoc{Records: []json.RawMessage{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	// Validate the stored declaration before changing anything. An explicit
	// enabled:false is a legal off state, but a disabled rule still has to
	// carry complete, in-range parameters; a missing or null rule object or
	// field, a wrong type, an out-of-range number, an unknown or duplicate
	// field all fail here. intactVersion returns the built-in version for
	// the built-in id and an unknown-version error for an id it cannot find.
	v, err := intactVersion(data.Versions, id)
	if err != nil {
		return RuleVersion{}, err
	}
	if data.EnabledVersion == id {
		return v, nil
	}
	data.EnabledVersion = id
	if err := writeArchiveAtomic(dir, data); err != nil {
		return RuleVersion{}, err
	}
	return v, nil
}

// identifiableVersionID recovers the best human-recognizable identifier a
// stored version document still carries for an error message: the last
// string occurrence of its id key, recognising it the way the decoder folds
// field names — "id", "ID" and "ıd"-style compatibility spellings all
// count. The last occurrence is what a plain unmarshal surfaces, so a
// decayed document that repeats the id key ("id":"x","id":"y") is reported
// under the id a reader sees in the decoded file rather than claimed to be
// the earlier one. A document that is not an object, or carries no string
// id at all, has no identifiable version; its corruption is still reported
// (ParseRuleVersion judges the document), just without a made-up name.
func identifiableVersionID(entry json.RawMessage) string {
	const unidentifiable = "unidentifiable version"
	dec := json.NewDecoder(bytes.NewReader(entry))
	first, err := dec.Token()
	if err != nil {
		return unidentifiable
	}
	if d, ok := first.(json.Delim); !ok || d != '{' {
		return unidentifiable
	}
	idField := foldName("id")
	last := ""
	found := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return unidentifiable
		}
		key, _ := keyTok.(string)
		valTok, err := dec.Token()
		if err != nil {
			return unidentifiable
		}
		if _, isDelim := valTok.(json.Delim); isDelim {
			// Consume the container the id (or another key) points at; an
			// object/array id is a wrong type, not an identifier.
			depth := 1
			for depth > 0 {
				tok, err := dec.Token()
				if err != nil {
					return unidentifiable
				}
				if dd, ok := tok.(json.Delim); ok {
					if dd == '{' || dd == '[' {
						depth++
					} else {
						depth--
					}
				}
			}
			continue
		}
		if foldName(key) == idField {
			if s, ok := valTok.(string); ok && s != "" {
				last, found = s, true
			}
		}
	}
	if !found {
		return unidentifiable
	}
	return last
}

// ListVersions returns the built-in version plus every version registered
// in the archive, along with the currently enabled version ID.
//
// Every registered version's stored archive document must still satisfy
// the registration rules in full — sandwich and displacement each
// declaring enabled and severity, displacement also multiplier, severity
// an integer 1-5 and multiplier an integer 2-100 — re-validated from its
// raw bytes with the same parser registration, enable, comparison, replay
// and show use, before a single version is returned. The decoded struct
// cannot tell a missing or null enabled, severity or multiplier from an
// explicitly declared one (a missing enabled renders as false, a missing
// multiplier as 0), and a wrong-typed field fails the whole-archive decode
// before any judgment can run; listing off the structs directly would
// therefore display a decayed declaration with silently zeroed parameters,
// erasing the difference between a genuinely switched-off rule and a lost
// field. Unknown rules or fields and repeated fields in one object
// (including the case-folded and escaped spellings registration rejects)
// are damage of the same kind. One corrupt registered version therefore
// fails the whole listing with ErrCorruptVersion — whether or not it is
// the enabled one, wherever it sits in the archive — naming the version's
// identifiable stored id and the offending rule or field; no full or
// partial list is returned, and the corrupt entry is never skipped past,
// repaired, completed or replaced by the enabled version, the built-in
// rules or defaults.
//
// An explicitly declared enabled:false is a legal off state: such a
// version, including one with both rules disabled, is listed normally
// with its complete parameters. The built-in version leads the list,
// registered versions follow in stored order with their id strings
// verbatim, and the enabled marker is reported as builtin when the
// archive names none. A missing archive directory or a legacy archive
// without versions and an enabled marker yields just the built-in
// version with its original parameters; a wholly unparseable archive
// stays an archive-corruption error rather than "no versions". The
// query is read-only: it never repairs, completes, deletes or rewrites
// any stored declaration or anything else in the archive.
func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
	if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
		return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return nil, "", err
	}
	defer lock.Close()

	// Decode with each registered version kept as its raw stored document,
	// the same shape every other version query uses: a wrong-typed field in
	// one version is that version's corruption rather than whole-archive
	// corruption, and every entry is judged on its own before the list is
	// returned — listing never zero-fills, completes or drops an entry.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return nil, "", err
	}
	data := replayArchiveDoc{Records: []json.RawMessage{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return nil, "", fmt.Errorf("archive is corrupted: %w", err)
		}
	}

	versions = make([]RuleVersion, 0, len(data.Versions)+1)
	versions = append(versions, BuiltinVersion())
	for _, entry := range data.Versions {
		v, perr := ParseRuleVersion(entry)
		if perr != nil {
			return nil, "", fmt.Errorf("%w: %s: %w", ErrCorruptVersion, identifiableVersionID(entry), perr)
		}
		versions = append(versions, v)
	}
	enabled = data.EnabledVersion
	if enabled == "" {
		enabled = BuiltinVersionID
	}
	return versions, enabled, nil
}

// GetVersion returns one version's full parameters by ID. The requested
// version's stored archive document must still satisfy every registration
// rule in full — re-validated from its raw bytes with the same parser
// registrations pass — before its parameters are returned: the decoded
// struct cannot tell a missing enabled, severity or multiplier from an
// explicitly declared one, so a corrupt declaration would otherwise be
// shown with silently zeroed or defaulted parameters. An explicit
// enabled:false is a legal off state, but a disabled rule still has to
// carry complete, in-range parameters; a missing or null rule object or
// field, a wrong type, an out-of-range number, an unknown or duplicate
// field all fail with ErrCorruptVersion naming the version and the
// offending rule or field — never completed from defaults, the enabled
// version or the built-in rules. Only the requested version is judged: a
// corrupt sibling — even the currently enabled one — does not block
// showing an intact version, and an id that no stored declaration carries
// stays an ErrUnknownVersion failure (the id string is matched exactly,
// never case-folded or trimmed). The built-in version is constructed in
// code and always queryable, whether or not the archive directory exists.
// A wholly unparseable archive still fails as archive corruption. The
// query is read-only: version declarations, the enabled marker and the
// archived reports are never modified.
func GetVersion(dir, id string) (RuleVersion, error) {
	if id == BuiltinVersionID {
		return BuiltinVersion(), nil
	}
	if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return RuleVersion{}, err
	}
	defer lock.Close()

	// Decode with each registered version kept as its raw stored document,
	// the same shape a replay or an enable uses: a wrong-typed field in one
	// version is that version's corruption rather than whole-archive
	// corruption, and a corrupt sibling cannot block an intact candidate.
	raw, err := readArchiveBytes(dir)
	if err != nil {
		return RuleVersion{}, err
	}
	data := replayArchiveDoc{Records: []json.RawMessage{}}
	if raw != nil {
		if err := json.Unmarshal(raw, &data); err != nil {
			return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	return intactVersion(data.Versions, id)
}

// FindingChange pairs the archived and compared conclusions for one
// transaction whose kind or severity differs between the two versions.
type FindingChange struct {
	TxHash   string        `json:"txHash"`
	Original ReportFinding `json:"original"`
	Compared ReportFinding `json:"compared"`
}

// CompareResult is the outcome of re-judging one archived block under a
// different rule version. It carries both versions' parameters, both full
// conclusion sets, the raw swap evidence, and the per-transaction diff.
type CompareResult struct {
	ChainID          string          `json:"chainId"`
	BlockHash        string          `json:"blockHash"`
	BlockNumber      int64           `json:"blockNumber"`
	OriginalVersion  RuleVersion     `json:"originalVersion"`
	ComparedVersion  RuleVersion     `json:"comparedVersion"`
	OriginalFindings []ReportFinding `json:"originalFindings"`
	ComparedFindings []ReportFinding `json:"comparedFindings"`
	Swaps            []Swap          `json:"swaps"`
	Added            []ReportFinding `json:"added"`
	Removed          []ReportFinding `json:"removed"`
	Changed          []FindingChange `json:"changed"`
}

// compareArchiveDoc mirrors the archive file the way a comparison reads
// it: the embedded version declaration of every record is kept as its raw
// stored document (queryRecord), the same shape a report query, a replay
// and alert generation use, and each registered version is kept raw too.
// A wrong-typed or decayed field in one saved declaration then cannot
// break the read or masquerade as whole-archive corruption, and — crucially
// — cannot decode into silently zeroed parameters or be explained as the
// built-in rules from a written null: the target record's declaration is
// judged on its own from those bytes before any comparison is returned.
type compareArchiveDoc struct {
	Records  []queryRecord     `json:"records"`
	Versions []json.RawMessage `json:"versions"`
}

// Compare re-runs detection for one archived block under the given
// registered version and diffs the conclusions against the archived
// report. It only reads the archive: the original input file is not
// needed, and neither the archived report nor the enabled version is
// modified.
//
// The historical side is the target block's own saved report and is held
// to exactly the integrity proof a report query enforces before any
// result is returned: its declaration is re-validated from the raw stored
// bytes — a non-empty id, sandwich and displacement each declaring a
// boolean enabled and an integer severity 1-5, and a displacement
// multiplier 2-100; a missing or null field or rule object, a wrong type,
// an out-of-range number, an unknown field or rule, or a field declared
// twice in one object (an exact repeat, an escaped spelling or a
// case-only spelling naming the same field, even with identical values;
// the two rules declaring their own parameters side by side is not a
// repeat) makes the saved declaration corrupt. An explicit enabled:false
// is a legal off state, but the disabled rule still has to carry
// complete, in-range parameters. Only an old-format record with no
// version key at all keeps the built-in interpretation: a written null,
// an empty object or an incomplete declaration is corruption, and an id
// of "builtin" names the same saved declaration and cannot bypass the
// check. A legal candidate version never rescues a damaged historical
// declaration: the whole comparison fails with ErrCorruptVersion naming
// the target chain and block, the readable saved version id and the
// offending rule or field — even when the block has no swaps or its
// archived findings are empty, so no empty comparison can skip the
// proof. The historical parameters come from that report alone, never
// from the currently enabled or a same-id registered version, and the
// saved id need not still be registered.
//
// The named candidate version's stored document must likewise still
// satisfy the registration rules in full; a corrupt one fails with
// ErrCorruptVersion rather than comparing under zeroed or substituted
// parameters. An unknown block stays ErrUnknownBlock and an unknown or
// corrupt candidate version keeps its existing error behavior.
func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
	if _, err := os.Stat(dir); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return CompareResult{}, ErrUnknownBlock
		}
		return CompareResult{}, err
	}
	lock, err := lockArchive(dir, syscall.LOCK_SH)
	if err != nil {
		return CompareResult{}, err
	}
	defer lock.Close()

	raw, err := readArchiveBytes(dir)
	if err != nil {
		return CompareResult{}, err
	}
	var doc compareArchiveDoc
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &doc); err != nil {
			return CompareResult{}, fmt.Errorf("archive is corrupted: %w", err)
		}
	}
	var rec *queryRecord
	for i := range doc.Records {
		if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
			rec = &doc.Records[i]
			break
		}
	}
	if rec == nil {
		return CompareResult{}, ErrUnknownBlock
	}
	// The historical side is this block's own saved report and has to pass
	// exactly the integrity proof a report query demands before any result
	// is returned — re-validated from the declaration's raw stored bytes,
	// not the decoded struct. A written null would otherwise leave the
	// version pointer nil and be explained as the built-in rules, and a
	// missing enabled/severity/multiplier would decode as an explicit zero
	// value and compare under silently zeroed parameters; an empty object,
	// a wrong type, an out-of-range number, an unknown rule or field and a
	// repeated field are damage of the same kind. A legal candidate can
	// never rescue this declaration, and the check runs unconditionally —
	// even for a block with no swaps or an empty findings array — so no
	// empty comparison can skip it. Only a wholly absent version key (a
	// zero-length RawMessage) is the legacy shape explained by builtin.
	originalVersion, err := archivedReportVersion(rec.Version)
	if err != nil {
		return CompareResult{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
	}
	// The requested candidate version must also be intact in the archive:
	// re-validate its stored document before judging anything, so a corrupt
	// version fails the same way even when the block has no swaps and
	// detection would produce no conclusions at all.
	compared, err := intactVersion(doc.Versions, versionID)
	if err != nil {
		return CompareResult{}, err
	}
	original := rec.Findings
	if original == nil {
		original = []ReportFinding{}
	}
	rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
	swaps := rec.Swaps
	if swaps == nil {
		swaps = []Swap{}
	}

	origByTx := make(map[string]ReportFinding, len(original))
	for _, f := range original {
		origByTx[f.TxHash] = f
	}
	compByTx := make(map[string]ReportFinding, len(rejudged))
	for _, f := range rejudged {
		compByTx[f.TxHash] = f
	}
	added := []ReportFinding{}
	removed := []ReportFinding{}
	changed := []FindingChange{}
	for _, f := range rejudged {
		if o, ok := origByTx[f.TxHash]; ok {
			// A transaction present on both sides with a different kind or
			// severity is a change, never an add plus a remove.
			if o.Kind != f.Kind || o.Severity != f.Severity {
				changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
			}
		} else {
			added = append(added, f)
		}
	}
	for _, f := range original {
		if _, ok := compByTx[f.TxHash]; !ok {
			removed = append(removed, f)
		}
	}
	byTx := func(fs []ReportFinding) {
		sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
	}
	byTx(added)
	byTx(removed)
	sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })

	return CompareResult{
		ChainID:          rec.ChainID,
		BlockHash:        rec.BlockHash,
		BlockNumber:      rec.BlockNumber,
		OriginalVersion:  originalVersion,
		ComparedVersion:  compared,
		OriginalFindings: original,
		ComparedFindings: rejudged,
		Swaps:            swaps,
		Added:            added,
		Removed:          removed,
		Changed:          changed,
	}, nil
}

