1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"syscall"
14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// swapLine mirrors one swap record inside a block line. Pointers
67	// distinguish a missing field (or an explicit null) from an explicit
68	// zero value: a replay record must be complete on its own, so In, Out,
69	// GasPrice and Index are all required and may not be null.
70	type swapLine struct {
71		TxHash   *string `json:"TxHash"`
72		Pool     *string `json:"Pool"`
73		Trader   *string `json:"Trader"`
74		In       *int64  `json:"In"`
75		Out      *int64  `json:"Out"`
76		GasPrice *int64  `json:"GasPrice"`
77		Index    *int    `json:"Index"`
78	}
79	
80	// blockLine mirrors one input line. Pointers distinguish a missing field
81	// from an explicit zero value.
82	type blockLine struct {
83		ChainID     *string     `json:"chainId"`
84		BlockHash   *string     `json:"blockHash"`
85		BlockNumber *int64      `json:"blockNumber"`
86		Swaps       *[]swapLine `json:"swaps"`
87	}
88	
89	func parseBlock(text string) (Block, error) {
90		var raw blockLine
91		dec := json.NewDecoder(strings.NewReader(text))
92		if err := dec.Decode(&raw); err != nil {
93			return Block{}, fmt.Errorf("invalid JSON: %w", err)
94		}
95		if err := blockTrailingData(text, int(dec.InputOffset())); err != nil {
96			return Block{}, err
97		}
98		if raw.ChainID == nil || *raw.ChainID == "" {
99			return Block{}, errors.New("chainId must be a non-empty string")
100		}
101		if raw.BlockHash == nil || *raw.BlockHash == "" {
102			return Block{}, errors.New("blockHash must be a non-empty string")
103		}
104		if raw.BlockNumber == nil {
105			return Block{}, errors.New("blockNumber is required")
106		}
107		if *raw.BlockNumber < 0 {
108			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
109		}
110		if raw.Swaps == nil {
111			return Block{}, errors.New("swaps must be an array")
112		}
113	
114		byTx := make(map[string]Swap)
115		byIndex := make(map[int]string)
116		swaps := []Swap{}
117		for i, s := range *raw.Swaps {
118			if s.TxHash == nil || *s.TxHash == "" {
119				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
120			}
121			if s.Pool == nil || *s.Pool == "" {
122				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
123			}
124			if s.Trader == nil || *s.Trader == "" {
125				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
126			}
127			// Every numeric field must be present and non-null in this very
128			// record; an explicit zero is a valid value, never a missing one.
129			// Values must not be borrowed from a neighbour, a same-hash record
130			// or a default, so an incomplete record is rejected before dedup
131			// even when a complete record with the same tx hash exists.
132			for _, f := range []struct {
133				name string
134				v    *int64
135			}{
136				{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
137			} {
138				if f.v == nil {
139					return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
140				}
141			}
142			if s.Index == nil {
143				return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
144			}
145			in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
146			if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
147				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
148			}
149			swap := Swap{
150				TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
151				In: in, Out: out, GasPrice: gasPrice, Index: index,
152			}
153			if prev, ok := byTx[swap.TxHash]; ok {
154				if prev != swap {
155					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
156				}
157				continue // exact duplicate, keep one copy
158			}
159			if other, ok := byIndex[swap.Index]; ok {
160				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
161			}
162			byTx[swap.TxHash] = swap
163			byIndex[swap.Index] = swap.TxHash
164			swaps = append(swaps, swap)
165		}
166		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
167		return Block{
168			ChainID:     *raw.ChainID,
169			BlockHash:   *raw.BlockHash,
170			BlockNumber: *raw.BlockNumber,
171			Swaps:       swaps,
172		}, nil
173	}
174	
175	// blockTrailingData names the first non-whitespace byte after the block
176	// object on a replay line, so an unmatched '}' or ']' — or a second value
177	// of any kind — is reported directly; only whitespace may follow the
178	// object. dec.More cannot see this: after a complete top-level value it
179	// only looks for the start of another value and treats stray closing
180	// brackets as "nothing more".
181	func blockTrailingData(text string, offset int) error {
182		rest := strings.TrimLeft(text[offset:], " \t\n\r")
183		if len(rest) > 0 {
184			return fmt.Errorf("invalid JSON: unexpected trailing data after block object: %s", trailingTokenName(rest[0]))
185		}
186		return nil
187	}
188	
189	func swapsEqual(a, b []Swap) bool {
190		if len(a) != len(b) {
191			return false
192		}
193		for i := range a {
194			if a[i] != b[i] {
195				return false
196			}
197		}
198		return true
199	}
200	
201	// sameContent reports whether two blocks carry the same content. Both sides
202	// are canonical (deduplicated, sorted by Index), so ordering and exact
203	// duplicates in the input do not affect the comparison.
204	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
205		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
206	}
207	
208	// DetectBlock checks every swap against its adjacent neighbours within its
209	// pool under the built-in rules. See DetectBlockWithRules.
210	func DetectBlock(swaps []Swap) []ReportFinding {
211		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
212	}
213	
214	// DetectBlockWithRules checks every swap against its adjacent neighbours
215	// within its pool under the given rule version: a sandwich when the same
216	// trader brackets the victim with higher gas on both sides, otherwise a
217	// displacement when the previous swap's gas strictly exceeds the configured
218	// multiple of the victim's. The last swap of a pool is checked too. An
219	// enabled sandwich takes priority over displacement for the same victim;
220	// with the sandwich rule off the victim can still be flagged for
221	// displacement. With both rules off the result is an empty slice. The
222	// judgment itself is shared with Detect; this entry only adds the block
223	// report's raw-swap evidence and ordering.
224	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
225		pools := make(map[string][]Swap)
226		for _, s := range swaps {
227			pools[s.Pool] = append(pools[s.Pool], s)
228		}
229		findings := []ReportFinding{}
230		for _, pool := range pools {
231			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
232			for i, victim := range pool {
233				var front, back *Swap
234				if i > 0 {
235					front = &pool[i-1]
236				}
237				if i+1 < len(pool) {
238					back = &pool[i+1]
239				}
240				j, hit := judgeVictim(front, victim, back, rules)
241				if !hit {
242					continue
243				}
244				// The evidence keeps the full swap fields of every record that
245				// participated: front, victim, and for a sandwich also back.
246				evidence := []Swap{*front, victim}
247				if j.kind == "sandwich" {
248					evidence = append(evidence, *back)
249				}
250				findings = append(findings, ReportFinding{
251					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
252					Evidence: evidence,
253				})
254			}
255		}
256		sort.Slice(findings, func(i, j int) bool {
257			if findings[i].Severity != findings[j].Severity {
258				return findings[i].Severity > findings[j].Severity
259			}
260			return findings[i].TxHash < findings[j].TxHash
261		})
262		return findings
263	}
264	
265	// record is the archived form of a block: the report plus the canonical
266	// swaps, so a later import can detect content conflicts. Version carries
267	// the full rule parameters used for the findings; it is nil only in
268	// archives written before rule versions existed, which are interpreted
269	// under the built-in rules.
270	type record struct {
271		ChainID     string          `json:"chainId"`
272		BlockHash   string          `json:"blockHash"`
273		BlockNumber int64           `json:"blockNumber"`
274		Swaps       []Swap          `json:"swaps"`
275		Findings    []ReportFinding `json:"findings"`
276		Version     *RuleVersion    `json:"version,omitempty"`
277	}
278	
279	func (r record) ruleVersion() RuleVersion {
280		if r.Version != nil {
281			return *r.Version
282		}
283		return BuiltinVersion()
284	}
285	
286	// queryRecord mirrors one archived record the way a report query reads it.
287	// Every business field is decoded normally, but the archived rule-version
288	// declaration is kept as its raw stored document. The decoded struct cannot
289	// tell a missing field, an explicit null or a wrong-typed value from a real
290	// one: decoding the embedded version into the struct would show a decayed
291	// report under silently zeroed parameters (enabled false, severity 0, a
292	// zero displacement multiplier), and — because a null or incomplete
293	// declaration carries no usable id — risk explaining it as the built-in
294	// rules. A zero-length Version means the "version" key is absent entirely
295	// (a value-type RawMessage is left untouched for a missing key), which
296	// alone is the legacy, pre-version format interpreted under the built-in
297	// rules; any present value — the bytes "null", {} or an object — is kept
298	// byte for byte and must be re-validated from those bytes before the
299	// report is shown.
300	type queryRecord struct {
301		ChainID     string          `json:"chainId"`
302		BlockHash   string          `json:"blockHash"`
303		BlockNumber int64           `json:"blockNumber"`
304		Swaps       []Swap          `json:"swaps"`
305		Findings    []ReportFinding `json:"findings"`
306		Version     json.RawMessage `json:"version"`
307	}
308	
309	// archivedReportVersion proves the version declaration embedded in an
310	// archived record still satisfies every registration rule, re-validating
311	// the raw document with the same parser registrations pass. A wholly
312	// absent "version" key is the only legacy shape and means the built-in
313	// rules; anything actually saved — null, an empty object, an incomplete
314	// declaration, a wrong type, an out-of-range number, an unknown or
315	// duplicated field — is corruption rather than a zero-filled or built-in
316	// parameter set. An id of "builtin" names the same saved declaration and
317	// is validated just like any other id; it never bypasses the check.
318	func archivedReportVersion(raw json.RawMessage) (RuleVersion, error) {
319		if len(raw) == 0 {
320			return BuiltinVersion(), nil
321		}
322		return ParseRuleVersion(raw)
323	}
324	
325	// corruptReportError names the chain and block a failed report query
326	// targets, the saved version identifier when the document still carries a
327	// readable one (so corruption is not mistaken for an unregistered
328	// version), and the offending rule or field from the validation failure.
329	// It wraps both ErrCorruptVersion and the underlying cause (for example
330	// ErrDuplicateField).
331	func corruptReportError(chainID, blockHash string, raw json.RawMessage, cause error) error {
332		if id := identifiableVersionID(raw); id != "unidentifiable version" {
333			return fmt.Errorf("%w: archived report for chain %s block %s uses version %q: %w",
334				ErrCorruptVersion, chainID, blockHash, id, cause)
335		}
336		return fmt.Errorf("%w: archived report for chain %s block %s: %w",
337			ErrCorruptVersion, chainID, blockHash, cause)
338	}
339	
340	// reportFromQueryRecord builds the Report presented for one archived
341	// record, proving the complete version declaration the record archived
342	// before any conclusion is shown. A report query and an identical reimport
343	// take this same path, so a re-imported block whose content matches the
344	// archive is held to exactly the standard of a standalone report query:
345	// a wholly absent version key is the one legacy shape and means the
346	// built-in rules, while a declaration actually saved as null, as an empty
347	// object, only in part, with a wrong type or an out-of-range number, an
348	// unknown or repeated field — an id of "builtin" included — fails as
349	// ErrCorruptVersion naming the chain, the block, the readable saved id
350	// and the offending rule or field. The parameters are never zero-filled,
351	// borrowed from the enabled or a registered version, or re-detected; the
352	// archived findings, evidence and swap count are returned as stored.
353	func reportFromQueryRecord(rec *queryRecord) (Report, error) {
354		version, err := archivedReportVersion(rec.Version)
355		if err != nil {
356			return Report{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
357		}
358		return Report{
359			ChainID:     rec.ChainID,
360			BlockHash:   rec.BlockHash,
361			BlockNumber: rec.BlockNumber,
362			SwapCount:   len(rec.Swaps),
363			Version:     version,
364			Findings:    rec.Findings,
365		}, nil
366	}
367	
368	func (r record) report() Report {
369		return Report{
370			ChainID:     r.ChainID,
371			BlockHash:   r.BlockHash,
372			BlockNumber: r.BlockNumber,
373			SwapCount:   len(r.Swaps),
374			Version:     r.ruleVersion(),
375			Findings:    r.Findings,
376		}
377	}
378	
379	const (
380		archiveFileName = "archive.json"
381		lockFileName    = "lock"
382	)
383	
384	type archiveData struct {
385		Records []record `json:"records"`
386		// Versions and EnabledVersion are absent in archives written before
387		// rule versions existed; such archives run the built-in rules.
388		Versions       []RuleVersion `json:"versions,omitempty"`
389		EnabledVersion string        `json:"enabledVersion,omitempty"`
390		// Suppressions and AlertRecords are absent in archives written before
391		// offline alerting existed; such archives simply have no registered
392		// conditions and no processing history.
393		Suppressions []Suppression      `json:"suppressions,omitempty"`
394		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
395		// Reviews is absent in archives written before manual reviews existed;
396		// every conclusion then behaves as unreviewed.
397		Reviews []ReviewObject `json:"reviews,omitempty"`
398	}
399	
400	// readArchiveBytes returns the exact bytes of the archive file, or nil
401	// when no archive exists yet.
402	func readArchiveBytes(dir string) ([]byte, error) {
403		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
404		if errors.Is(err, os.ErrNotExist) {
405			return nil, nil
406		}
407		if err != nil {
408			return nil, err
409		}
410		return raw, nil
411	}
412	
413	func readArchive(dir string) (archiveData, error) {
414		raw, err := readArchiveBytes(dir)
415		if err != nil {
416			return archiveData{}, err
417		}
418		if raw == nil {
419			return archiveData{Records: []record{}}, nil
420		}
421		var data archiveData
422		if err := json.Unmarshal(raw, &data); err != nil {
423			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
424		}
425		return data, nil
426	}
427	
428	// replayArchiveDoc mirrors the archive file the way a replay reads and
429	// writes it: every record and every registered version is kept as its raw
430	// stored document, while suppressions, alert records and reviews are fully
431	// decoded. A corrupt document — a wrong-typed field, say — then cannot
432	// break the read or masquerade as whole-archive corruption; the version
433	// this run selects is judged on its own by intactVersion, and an already
434	// archived block whose content matches the input is judged on its own from
435	// its record's raw bytes exactly the way a report query proves it, rather
436	// than decoded into silently zeroed parameters or a null-explained
437	// built-in report. Entries the run does not touch are written back byte
438	// for byte: a replay never repairs, completes or drops a stored record or
439	// version, not even a corrupt one.
440	type replayArchiveDoc struct {
441		Records        []json.RawMessage  `json:"records"`
442		Versions       []json.RawMessage  `json:"versions,omitempty"`
443		EnabledVersion string             `json:"enabledVersion,omitempty"`
444		Suppressions   []Suppression      `json:"suppressions,omitempty"`
445		AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
446		Reviews        []ReviewObject     `json:"reviews,omitempty"`
447	}
448	
449	// writeArchiveAtomic replaces the archive file in one rename, so a crash
450	// can only expose the previous or the next complete commit, never a half
451	// written file.
452	func writeArchiveAtomic(dir string, data any) error {
453		raw, err := json.MarshalIndent(data, "", "  ")
454		if err != nil {
455			return err
456		}
457		tmp := filepath.Join(dir, archiveFileName+".tmp")
458		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
459		if err != nil {
460			return err
461		}
462		if _, err := f.Write(raw); err != nil {
463			f.Close()
464			os.Remove(tmp)
465			return err
466		}
467		if err := f.Sync(); err != nil {
468			f.Close()
469			os.Remove(tmp)
470			return err
471		}
472		if err := f.Close(); err != nil {
473			os.Remove(tmp)
474			return err
475		}
476		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
477			os.Remove(tmp)
478			return err
479		}
480		if d, err := os.Open(dir); err == nil {
481			d.Sync()
482			d.Close()
483		}
484		return nil
485	}
486	
487	// lockArchive takes an flock on the archive's lock file. The lock is
488	// released automatically if the process dies, so no stale locks survive.
489	func lockArchive(dir string, how int) (*os.File, error) {
490		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
491		if err != nil {
492			return nil, err
493		}
494		if err := syscall.Flock(int(f.Fd()), how); err != nil {
495			f.Close()
496			if errors.Is(err, syscall.EWOULDBLOCK) {
497				return nil, ErrBusy
498			}
499			return nil, err
500		}
501		return f, nil
502	}
503	
504	type parsedBlock struct {
505		line  int
506		block Block
507	}
508	
509	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
510		var out []parsedBlock
511		reader := bufio.NewReader(r)
512		lineNo := 0
513		for {
514			raw, err := reader.ReadBytes('\n')
515			if len(raw) > 0 {
516				lineNo++
517			}
518			if text := strings.TrimSpace(string(raw)); text != "" {
519				block, perr := parseBlock(text)
520				if perr != nil {
521					return nil, &LineError{Line: lineNo, Err: perr}
522				}
523				out = append(out, parsedBlock{line: lineNo, block: block})
524			}
525			if err == io.EOF {
526				return out, nil
527			}
528			if err != nil {
529				return nil, err
530			}
531		}
532	}
533	
534	// ReplayFile imports the line-delimited blocks in inputPath into the
535	// archive at dir and returns one report per distinct block, in order of
536	// first appearance. New blocks are judged under the archive's currently
537	// enabled rule version; that version's stored document must still satisfy
538	// the registration rules in full, or the whole replay fails with
539	// ErrCorruptVersion before any report is produced.
540	func ReplayFile(inputPath, dir string) ([]Report, error) {
541		return replayFile(inputPath, dir, "")
542	}
543	
544	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
545	// version instead of the archive's enabled one. The named version's stored
546	// document must still satisfy the registration rules in full; a corrupt
547	// one fails the whole replay with ErrCorruptVersion rather than judging
548	// under zeroed or substituted parameters.
549	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
550		if versionID == "" {
551			return nil, errors.New("version id must not be empty")
552		}
553		return replayFile(inputPath, dir, versionID)
554	}
555	
556	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
557		f, err := os.Open(inputPath)
558		if err != nil {
559			return nil, err
560		}
561		defer f.Close()
562		return doReplay(f, dir, versionID)
563	}
564	
565	// Replay parses, validates and archives blocks from r under the archive's
566	// currently enabled rule version. Every line is checked before anything is
567	// written; any failure leaves the archive untouched. New reports are
568	// committed together in a single atomic write. The selected version's
569	// stored document is re-validated before any block is judged: a corrupt
570	// version fails the whole replay with ErrCorruptVersion — never a
571	// substituted or zeroed parameter set — even when no input block would
572	// have triggered the damaged rule.
573	//
574	// A block that is already archived and arrives with identical content is
575	// not re-judged: its original report is returned. Before that report is
576	// returned the declaration the record archived is proved from its raw
577	// bytes by exactly the standard a standalone report query (Query)
578	// enforces — a non-empty id, both rules each declaring a boolean enabled
579	// and an integer severity 1-5, and a displacement multiplier 2-100 —
580	// rather than trusted because this run's own version is legal. A
581	// declaration saved as null, as an empty object, only in part, with a
582	// wrong type or out-of-range number, an unknown rule or field, or a field
583	// repeated in one object (the field-name folding and escapes included,
584	// even when both values agree) fails the whole replay with
585	// ErrCorruptVersion; an explicit enabled:false is a legal off state but a
586	// disabled rule still has to be declared completely. Only a wholly absent
587	// version key — the pre-version legacy shape — is explained by the
588	// built-in rules; a written "builtin" id is validated like every other.
589	// On failure no report is returned, no same-batch new block is saved and
590	// no archived content changes, regardless of where the corrupt old block
591	// sits relative to the new ones. An intact old report is returned with
592	// its originally saved conclusions, evidence, swap count and full
593	// parameters, never re-detected and never completed from the currently
594	// enabled or a same-id registered version; its historical id need not
595	// still be registered.
596	func Replay(input io.Reader, dir string) ([]Report, error) {
597		return doReplay(input, dir, "")
598	}
599	
600	// ReplayWithVersion is Replay under an explicitly registered rule version
601	// instead of the archive's enabled one, with the same integrity check: a
602	// corrupt stored version document fails the whole replay with
603	// ErrCorruptVersion before any report is produced.
604	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
605		if versionID == "" {
606			return nil, errors.New("version id must not be empty")
607		}
608		return doReplay(input, dir, versionID)
609	}
610	
611	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
612		parsed, err := parseBlocks(input)
613		if err != nil {
614			return nil, err
615		}
616	
617		// Collapse repeated identities within this file, keeping first
618		// appearance order; conflicting content rejects the whole file.
619		type occurrence struct {
620			block Block
621			line  int
622		}
623		order := []occurrence{}
624		firstSeen := make(map[blockID]int)
625		for _, p := range parsed {
626			id := blockID{p.block.ChainID, p.block.BlockHash}
627			if first, ok := firstSeen[id]; ok {
628				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
629					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
630						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
631				}
632				continue
633			}
634			firstSeen[id] = len(order)
635			order = append(order, occurrence{block: p.block, line: p.line})
636		}
637	
638		if err := os.MkdirAll(dir, 0o755); err != nil {
639			return nil, err
640		}
641		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
642		if err != nil {
643			return nil, err
644		}
645		defer lock.Close()
646	
647		// Decode with every stored record and registered version kept as its
648		// raw stored document, so a wrong-typed field in one entry is that
649		// entry's corruption, not whole-archive corruption: the selected
650		// version's document is re-validated from its bytes the same way a
651		// single-block comparison proves its version intact, and each already
652		// archived block this run re-imports is proved from its record's raw
653		// bytes the same way a standalone report query proves it, rather than
654		// decoded into silently zeroed parameters or a null-explained
655		// built-in report.
656		raw, err := readArchiveBytes(dir)
657		if err != nil {
658			return nil, err
659		}
660		data := replayArchiveDoc{Records: []json.RawMessage{}}
661		if raw != nil {
662			if err := json.Unmarshal(raw, &data); err != nil {
663				return nil, fmt.Errorf("archive is corrupted: %w", err)
664			}
665		}
666		// Resolve the version once, while the exclusive lock is held: every
667		// new block in this run is judged under the same rules even if another
668		// process enables a different version right after we finish. The
669		// selected version's stored document must still satisfy the
670		// registration rules in full; a corrupt one fails the whole replay
671		// with ErrCorruptVersion here, before any block is judged, any report
672		// is produced or anything is written — even when the input is empty,
673		// holds only blocks already archived, or would never trigger the
674		// damaged rule. The corrupt content is never replaced by the enabled
675		// version, the built-in rules or defaults.
676		version, err := resolveReplayVersion(data, versionID)
677		if err != nil {
678			return nil, err
679		}
680		// Index the stored records by block identity with their decoded
681		// content; the embedded version stays raw until an identical reimport
682		// actually has to present that record's report, when its saved
683		// declaration is proved exactly as a report query would.
684		stored := make([]queryRecord, len(data.Records))
685		archived := make(map[blockID]int, len(data.Records))
686		for i, rawRec := range data.Records {
687			var qr queryRecord
688			if err := json.Unmarshal(rawRec, &qr); err != nil {
689				return nil, fmt.Errorf("archive is corrupted: record %d: %w", i, err)
690			}
691			stored[i] = qr
692			archived[blockID{qr.ChainID, qr.BlockHash}] = i
693		}
694	
695		reports := make([]Report, 0, len(order))
696		newRecords := []json.RawMessage{}
697		for _, occ := range order {
698			id := blockID{occ.block.ChainID, occ.block.BlockHash}
699			if idx, ok := archived[id]; ok {
700				rec := stored[idx]
701				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
702					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
703						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
704				}
705				// Identical re-import: return the original report, add nothing.
706				// The saved declaration is held to the standard of a standalone
707				// report query before any conclusion is returned — never read as
708				// built-in from a null version or as zeroed parameters from an
709				// incomplete one, and never completed from the version this run
710				// selected. A corrupt declaration fails the whole batch here,
711				// before a single new block is committed, whether the old block
712				// appears before or after the new ones.
713				report, perr := reportFromQueryRecord(&rec)
714				if perr != nil {
715					return nil, &LineError{Line: occ.line, Err: perr}
716				}
717				reports = append(reports, report)
718				continue
719			}
720			rec := record{
721				ChainID:     occ.block.ChainID,
722				BlockHash:   occ.block.BlockHash,
723				BlockNumber: occ.block.BlockNumber,
724				Swaps:       occ.block.Swaps,
725				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
726				Version:     &version,
727			}
728			rawRec, perr := json.Marshal(rec)
729			if perr != nil {
730				return nil, perr
731			}
732			newRecords = append(newRecords, rawRec)
733			reports = append(reports, rec.report())
734		}
735		// All blocks passed — new and identical alike — so commit the new
736		// records once, leaving every stored record's raw bytes untouched.
737		if len(newRecords) > 0 {
738			data.Records = append(data.Records, newRecords...)
739			if err := writeArchiveAtomic(dir, data); err != nil {
740				return nil, err
741			}
742		}
743		return reports, nil
744	}
745	
746	// resolveReplayVersion picks the rule version for one replay run — the
747	// explicitly requested one, or the archive's currently enabled version —
748	// and proves its stored archive document still satisfies every
749	// registration rule, re-validating the raw document with the same parser
750	// registrations pass. The decoded struct cannot do this: a missing
751	// enabled, severity or multiplier field unmarshals as the zero value and
752	// is indistinguishable from an explicitly declared one, and a zero
753	// displacement multiplier even crashes detection. An explicitly declared
754	// false or any in-range value is valid; a missing or null field, a wrong
755	// type or an out-of-range number makes the version corrupt, and the
756	// failure names the version and the offending rule or field. Archives
757	// written before rule versions existed have no enabled marker and run the
758	// built-in rules; the built-in version is constructed in code and always
759	// intact.
760	func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
761		id := versionID
762		if id == "" {
763			id = data.EnabledVersion
764			if id == "" {
765				return BuiltinVersion(), nil
766			}
767		}
768		return intactVersion(data.Versions, id)
769	}
770	
771	// queryArchiveDoc mirrors just the records a report query reads, keeping
772	// each record's embedded version declaration as its raw stored document —
773	// the same shape registered versions are kept in everywhere else — so a
774	// wrong-typed field in one report's declaration fails that report's query
775	// rather than breaking the whole-archive decode or decoding into silently
776	// zeroed parameters.
777	type queryArchiveDoc struct {
778		Records []queryRecord `json:"records"`
779	}
780	
781	// Query returns the archived report for one block identity. It only reads
782	// the archive; the original input file is not needed, and neither a
783	// successful nor a failed query rewrites anything.
784	//
785	// Before the report is returned, the complete version declaration the
786	// report archived is re-validated from its raw bytes with the same proof
787	// registration, enable, comparison, evaluation and replay demand: a
788	// non-empty version identifier, both the sandwich and displacement rules
789	// each with a boolean enabled and an integer severity in 1-5, and the
790	// displacement multiplier an integer in 2-100. A missing or null field or
791	// rule object, a wrong type, an out-of-range number, an unknown field or
792	// rule, or a field declared twice in one object (an exact repeat, an
793	// escaped spelling or a case-only spelling that names the same field —
794	// even when both values agree) makes the saved declaration corrupt. An
795	// explicit enabled:false is a legal off state, not damage; the disabled
796	// rule still has to carry complete, in-range parameters.
797	//
798	// Only an old-format record with no "version" key at all keeps the
799	// original built-in interpretation. A declaration actually saved as null,
800	// as an empty object or only in part is corruption, and an id of
801	// "builtin" is validated like every other id rather than bypassing the
802	// check. On corruption Query fails with ErrCorruptVersion naming the
803	// target chain and block, the readable saved version id and the offending
804	// rule or field; it never zero-fills the parameters, explains them as
805	// built-in, or substitutes parameters from the currently enabled or a
806	// registered version. The report uses the parameters it archived and is
807	// never re-detected. A block that was never archived stays
808	// ErrUnknownBlock.
809	func Query(dir, chainID, blockHash string) (Report, error) {
810		if _, err := os.Stat(dir); err != nil {
811			if errors.Is(err, os.ErrNotExist) {
812				return Report{}, ErrUnknownBlock
813			}
814			return Report{}, err
815		}
816		lock, err := lockArchive(dir, syscall.LOCK_SH)
817		if err != nil {
818			return Report{}, err
819		}
820		defer lock.Close()
821	
822		raw, err := readArchiveBytes(dir)
823		if err != nil {
824			return Report{}, err
825		}
826		var doc queryArchiveDoc
827		if len(raw) > 0 {
828			if err := json.Unmarshal(raw, &doc); err != nil {
829				return Report{}, fmt.Errorf("archive is corrupted: %w", err)
830			}
831		}
832		idx := -1
833		for i := range doc.Records {
834			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
835				idx = i
836				break
837			}
838		}
839		if idx < 0 {
840			return Report{}, ErrUnknownBlock
841		}
842		rec := &doc.Records[idx]
843		return reportFromQueryRecord(rec)
844	}
845

